import * as React from 'react';
import { Component } from 'react';
import { Rnd } from 'react-rnd';

type DraggableData = {
  node: HTMLElement;
  x: number;
  y: number;
  deltaX: number;
  deltaY: number;
  lastX: number;
  lastY: number;
};

interface VideoRoomContainerProps {
  onContextMenu: (event: any, ref: any) => void;
  onDragStart: (e, d: DraggableData) => void;
  onDrag: (e, d: DraggableData) => void;
  onDragStop: (e, d: DraggableData) => void;
  onResizeStart: (e, dir, ref) => void;
  onResize: (e, direction, ref, delta, position) => void;
  onResizeStop: (e, direction, ref, delta, position) => void;
  disableDragging: boolean;
  width: number;
  height: number;
  x: number;
  y: number;
}

export class VideoRoomContainer extends Component<VideoRoomContainerProps, Record<string, never>> {
  ref;

  constructor(props) {
    super(props);

    this.state = {};
  }

  render() {
    return (
      <Rnd
        onContextMenu={event => this.props.onContextMenu(event, this.ref)}
        ref={c => {
          this.ref = c;
        }}
        size={{
          width: this.props.width,
          height: this.props.height,
        }}
        position={{
          x: this.props.x,
          y: this.props.y,
        }}
        onDragStart={this.props.onDragStart}
        onDrag={this.props.onDrag}
        onDragStop={this.props.onDragStop}
        onResizeStart={(e, dir, ref) => {
          this.props.onResizeStart(e, dir, ref);
        }}
        onResize={(e, direction, ref, delta, position) => {
          this.props.onResize(e, direction, ref, delta, position);
        }}
        onResizeStop={(e, direction, ref, delta, position) => {
          this.props.onResizeStop(e, direction, ref, delta, position);
        }}
        style={{
          zIndex: 1300,
        }}
        enableResizing={{
          bottom: true,
          bottomLeft: true,
          bottomRight: true,
          left: true,
          right: true,
          top: true,
          topLeft: true,
          topRight: true,
        }}
        disableDragging={this.props.disableDragging}
        cancel={'.controls'}
        bounds="window" //"parent" "body" ".fooClassName"
        //lockAspectRatio={true}
        //lockAspectRatioExtraWidth={100}
        //lockAspectRatioExtraHeight={120}
        //minWidth={200}
        //minHeight={200}
        //maxWidth
        //maxHeight
        /*
                resizeHandleStyles={{
                    bottom: {}, //React.CSSProperties,
                    bottomLeft: {},
                    bottomRight: {},
                    left: {},
                    right: {},
                    top: {},
                    topLeft: {},
                    topRight: {}
                }}
                resizeHandleComponent={{
                    top: <div> </div>,  //React.ReactElement<any>,
                    right: <div> </div>, 
                    bottom: <div> </div>,
                    left: <div> </div>,
                    bottomRight: <div> </div>,
                    bottomLeft: <div> </div>,
                    topLeft: <div> </div>
                }}
                */
        //resizeHandleWrapperStyle={{}}
        //enableUserSelectHack={true}
        //allowAnyClick={true}
      >
        {this.props.children}
      </Rnd>
    );
  }
}
